mapper.select:
SELECT 
FROM mail_signature s
WHERE s.mail_sign_idx = #{signIdx}
  AND s.user_id       = #{userId}

mapper.update:
UPDATE mail_signature
SET default_new_yn = 'N',
    updated_at     = now()
WHERE user_id        = #{userId}
  AND default_new_yn = 'Y'

    AND mail_sign_idx != #{exceptIdx}

UPDATE mail_signature
SET default_reply_yn = 'N',
    updated_at       = now()
WHERE user_id          = #{userId}
  AND default_reply_yn = 'Y'

    AND mail_sign_idx != #{exceptIdx}

mapper.delete:
DELETE FROM mail_signature
WHERE mail_sign_idx = #{signIdx}
  AND user_id       = #{userId}

mapper.select:
SELECT COUNT(*)
FROM mail_signature s
WHERE s.user_id = #{userId}

SELECT COALESCE(MAX(s.sort_order) + 1, 0)
FROM mail_signature s
WHERE s.user_id = #{userId}
